type Runner = unsafe fn(u64) -> [u64; 3];
fn runner(name: &str) -> Runner {
    match name {
        "BossHook_AllSleeping" => run_BossHook_AllSleeping,
        "BossHook_DriveDeaths" => run_BossHook_DriveDeaths,
        "BossHook_Hold" => run_BossHook_Hold,
        "BossHook_Kind" => run_BossHook_Kind,
        "BossHook_Poll" => run_BossHook_Poll,
        "BossHook_Release" => run_BossHook_Release,
        "fn_8017C0C8" => run_fn_8017C0C8,
        "fn_8017C1A4" => run_fn_8017C1A4,
        "fn_8017C71C" => run_fn_8017C71C,
        "fn_8017C7A0" => run_fn_8017C7A0,
        "fn_8017C7EC" => run_fn_8017C7EC,
        "fn_8017D9C0" => run_fn_8017D9C0,
        "gm_8017C838" => run_gm_8017C838,
        "gm_8017C984" => run_gm_8017C984,
        "gm_8017C9A8" => run_gm_8017C9A8,
        "gm_8017CA38" => run_gm_8017CA38,
        "gm_8017CBAC" => run_gm_8017CBAC,
        "gm_8017CD94" => run_gm_8017CD94,
        "gm_8017CE34" => run_gm_8017CE34,
        "gm_8017CE34_CountEnemies" => run_gm_8017CE34_CountEnemies,
        "gm_8017CE34_GetCpuLevel" => run_gm_8017CE34_GetCpuLevel,
        "gm_8017CE34_SetupColors" => run_gm_8017CE34_SetupColors,
        "gm_8017D7AC" => run_gm_8017D7AC,
        _ => panic!("no runner for {name}"),
    }
}

#[test]
fn tu_gm_17c0_matches_c() {
    let data = include_str!("data/tu_gm_17c0.txt");
    unsafe { init(); }
    let mut bad: Vec<String> = Vec::new();
    let mut by_fn: std::collections::BTreeMap<String, (usize, usize)> = Default::default();
    for line in data.lines() {
        let mut it = line.split_whitespace();
        let name = it.next().unwrap();
        if let Ok(f) = std::env::var("TU_FN") { if f != name { continue; } }
        let seed = u64::from_str_radix(it.next().unwrap(), 16).unwrap();
        assert_eq!(it.next(), Some("="));
        let want: Vec<u64> = it.map(|x| u64::from_str_radix(x, 16).unwrap()).collect();
        let got = unsafe { runner(name)(seed) };
        let e = by_fn.entry(name.to_string()).or_default();
        e.0 += 1;
        if got[..] != want[..] {
            e.1 += 1;
            if e.1 <= 2 { bad.push(format!("{name} seed {seed:x}: C {want:x?} Rust {got:x?}")); }
            if e.1 == 1 && std::env::var("TU_OBJS").is_ok() { unsafe { eprintln!("MISMATCH {name} {seed:x}"); for (k, h) in rt::OBJ_HASH.iter().enumerate() { eprintln!("  rust obj {} {:x} size {}", rt::REGS[k].name, h, rt::REGS[k].size); } } }
        }
    }
    for (n, (t, b)) in &by_fn { if *b != 0 { eprintln!("FAIL {n}: {b}/{t} cases differ"); } }
    assert!(bad.is_empty(), "{} functions differ:\n{}", by_fn.values().filter(|v| v.1 != 0).count(), bad.join("\n"));
    eprintln!("{} functions, {} cases equal to the C", by_fn.len(), data.lines().count());
}
